local function load()
  local env = os.getenv("HRL_LIBRARY")
  if env and env ~= "" then return ffi.load(env) end
  local ok, lib = pcall(ffi.load, "hrldll")
  if ok then return lib end
  return ffi.load("hrl")
end
local C = load()
local M = { C = C, ffi = ffi, version = "0.8" }
local keep = {}  -- callbacks passed to native code stay referenced here

local function _mat(p) local t = {} for k = 0, 15 do t[k + 1] = p[k] end return t end
local function str(p) if p == nil then return nil end return ffi.string(p) end
local function arr(ct, t) if type(t) ~= "table" then return t, 0 end return ffi.new(ct .. "[?]", #t, t), #t end

